 *  Disimpan dalam Drive IPTG: folder gambar > "Borang Permohonan"
 * ========================================================== */
const TERMA_MOHON_ = ['Kenderaan pejabat adalah untuk urusan rasmi IPTG. Penggunaan untuk urusan peribadi hanya dalam keadaan khas dan tertakluk kepada kelulusan Pengarah.',
  'Kereta hanya boleh diambil selepas permohonan diluluskan oleh Pengarah dan disahkan oleh PIC.',
  'Guna dalam tempoh yang diluluskan sahaja. Lewat pulang akan direkod.',
  'Hanya pemohon boleh memandu. Lesen memandu mesti sah.',
  'Kos minyak, tol dan parkir ditanggung pemohon.',
  'Saman sepanjang tempoh pinjaman ditanggung pemohon.',
  'Kerosakan akibat kecuaian ditanggung pemohon.',
  'Pulangkan kereta dalam keadaan bersih, dengan minyak sekurang-kurangnya sama seperti semasa ambil.',
  'Lokasi GPS kereta direkod sepanjang penggunaan.',
  'Urusan rasmi IPTG sentiasa diutamakan. Kelulusan boleh dibatalkan jika kenderaan diperlukan untuk urusan rasmi.'];
function htmlBorangMohon_(ss, x) {
  x = x || {};
  const e = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const tz = 'Asia/Kuala_Lumpur';
  const f = (iso, p) => iso ? Utilities.formatDate(new Date(iso), tz, p || 'dd/MM/yyyy, h:mm a') : '';
  const tempoh = () => { if (!x.mula || !x.tamat) return ''; const j = Math.round((new Date(x.tamat) - new Date(x.mula)) / 3600000); return j >= 24 ? Math.floor(j / 24) + ' hari' + (j % 24 ? ' ' + (j % 24) + ' jam' : '') : j + ' jam'; };
  const row = (l, v) => '<tr><td class="l">' + l + '</td><td class="v">' + (v ? e(v) : '&nbsp;') + '</td></tr>';
  const kotak = on => '<span class="cb">' + (on ? '&#10003;' : '&nbsp;') + '</span>';
  const sign = (tajuk, nama, jawatan, tarikh) => '<td class="sg"><div class="sgT">' + tajuk + '</div><div class="sgL"></div><div class="sgN">' + e(nama || '') + '</div><div class="sgJ">' + e(jawatan || '') + '</div><div class="sgD">Tarikh: ' + (tarikh || '....................................') + '</div></td>';
  const st = String(x.status || '');
  const cop = st === 'LULUS' ? '<div class="cop ok">DILULUSKAN</div>' : st === 'DITOLAK' ? '<div class="cop no">TIDAK DILULUSKAN</div>' : '';
  const picNama = String(tetapan_(ss).picNama || '');
  const logo = 'data:image/png;base64,' + ICON_PNG_B64;
  return '<html><head><meta charset="utf-8"><style>' +
    '@page{size:A4;margin:14mm 14mm 14mm 14mm}' +
    'body{font-family:Arial,Helvetica,sans-serif;color:#10262c;font-size:10.5pt;margin:0}' +
    '.hd{width:100%;border-collapse:collapse;border-bottom:3px solid #0a7f86;margin-bottom:8px}.hd td{vertical-align:middle;padding:0 0 8px}' +
    '.logo{width:64px;height:64px;border-radius:12px}.org{font-size:12.5pt;font-weight:bold;color:#083b44;line-height:1.3}.alm{font-size:8.5pt;color:#5f7b80;margin-top:2px}' +
    '.ref{border:1px solid #0a7f86;border-radius:6px;padding:6px 8px;font-size:8.5pt;text-align:left;width:150px}.ref b{color:#0a7f86}' +
    '.tt{background:#0a7f86;color:#fff;text-align:center;font-weight:bold;font-size:11.5pt;padding:8px;letter-spacing:.3px;margin:6px 0 4px}' +
    '.st{text-align:center;font-size:8.5pt;color:#5f7b80;margin-bottom:8px}' +
    '.sk{background:#e6f7f6;color:#083b44;font-weight:bold;font-size:10pt;padding:5px 8px;margin:10px 0 0;border-left:4px solid #0a7f86}' +
    'table.t{width:100%;border-collapse:collapse}.t td{border:1px solid #c9dedd;padding:6px 8px;vertical-align:top}.t .l{width:34%;background:#f6fbfb;font-weight:bold;color:#083b44;font-size:9.5pt}' +
    'ol{margin:6px 0 4px 0;padding-left:18px;font-size:9pt;line-height:1.45}li{margin:1px 0}' +
    '.ak{font-size:9.5pt;margin:6px 0;padding:6px 8px;border:1px dashed #0a7f86;background:#fbfefe}' +
    '.cb{display:inline-block;width:12px;height:12px;border:1px solid #083b44;text-align:center;line-height:12px;font-size:9pt;margin-right:5px;vertical-align:middle}' +
    '.pl{font-size:10pt;margin:6px 0 2px}.pl span.o{margin-right:26px}' +
    'table.sgt{width:100%;border-collapse:collapse;margin-top:4px}.sg{width:50%;padding:4px 10px 0 0;vertical-align:top;font-size:9pt}' +
    '.sgT{color:#5f7b80}.sgL{border-bottom:1px solid #083b44;height:34px}.sgN{font-weight:bold;margin-top:3px}.sgJ{color:#5f7b80;font-size:8.5pt}.sgD{margin-top:4px;color:#5f7b80;font-size:8.5pt}' +
    '.cop{display:inline-block;border:3px solid;border-radius:8px;padding:4px 14px;font-weight:bold;font-size:13pt;letter-spacing:1px;transform:rotate(-6deg);margin:4px 0 0 6px}.cop.ok{color:#11734a;border-color:#11734a}.cop.no{color:#a61b1b;border-color:#a61b1b}' +
    '.ft{margin-top:12px;border-top:1px solid #c9dedd;padding-top:5px;font-size:7.5pt;color:#8aa0a3;text-align:center}' +
    '</style></head><body>' +
    '<table class="hd"><tr><td style="width:76px"><img class="logo" src="' + logo + '"></td>' +
    '<td><div class="org">INSTITUT PEMIKIRAN TOK GURU<br>DATO&#39; BENTARA SETIA (IPTG)</div><div class="alm">15503, Jalan Kota Darulnaim, Bandar Kota Bharu, 15050 Kota Bharu, Kelantan</div></td>' +
    '<td style="width:160px;text-align:right"><div class="ref"><b>No. Rujukan</b><br>' + e(x.id || '........................') + '<br><b>Tarikh Mohon</b><br>' + (x.masa ? f(x.masa, 'dd/MM/yyyy') : '........................') + '</div></td></tr></table>' +
    '<div class="tt">BORANG PERMOHONAN KHAS PENGGUNAAN KENDERAAN PEJABAT<br>(URUSAN PERIBADI)</div>' +
    '<div class="st">Tertakluk kepada kelulusan Pengarah. Borang ini hendaklah diisi dengan lengkap.</div>' +
    '<div class="sk">A. BUTIRAN PEMOHON</div><table class="t">' + row('Nama', x.nama) + row('Unit / Bahagian', x.unit) + row('No. telefon', x.tel) + '</table>' +
    '<div class="sk">B. BUTIRAN PENGGUNAAN</div><table class="t">' + row('Kenderaan', x.kenderaan) + row('Tarikh &amp; masa ambil', f(x.mula)) + row('Tarikh &amp; masa pulang', f(x.tamat)) +
      row('Tempoh', tempoh()) + row('Destinasi', x.destinasi) + row('Urusan / sebab', x.tujuan) + row('Bilangan orang', x.penumpang ? String(x.penumpang) : '') + '</table>' +
    '<div class="sk">C. TERMA &amp; SYARAT</div><ol>' + TERMA_MOHON_.map(t => '<li>' + e(t) + '</li>').join('') + '</ol>' +
    '<div class="ak">' + kotak(!!x.akuan) + 'Saya telah membaca dan bersetuju dengan semua terma dan syarat di atas.</div>' +
    '<table class="sgt"><tr>' + sign('Tandatangan pemohon', x.nama, 'Pemohon', x.masa ? f(x.masa, 'dd/MM/yyyy') : '') + '<td class="sg"></td></tr></table>' +
    '<div class="sk" style="page-break-before:always">D. ULASAN PENOLONG PENGARAH</div><div class="pl"><span class="o">' + kotak(false) + 'Disokong</span>' + kotak(false) + 'Tidak disokong</div>' +
    '<table class="t">' + row('Ulasan', '') + '</table>' +
    '<table class="sgt"><tr>' + sign('Tandatangan', 'MOHD HAFIZI BIN MAHADI', 'Penolong Pengarah', '') + '<td class="sg"></td></tr></table>' +
    '<div class="sk">E. KELULUSAN PENGARAH</div><div class="pl"><span class="o">' + kotak(st === 'LULUS') + 'Diluluskan</span>' + kotak(st === 'DITOLAK') + 'Tidak diluluskan ' + cop + '</div>' +
    '<table class="t">' + row('Catatan', x.catatan) + '</table>' +
    '<table class="sgt"><tr>' + sign('Tandatangan &amp; cop', "PROF. EMERITUS DATO' DR. JOHARI BIN MAT", 'Pengarah', x.masaPutus ? f(x.masaPutus, 'dd/MM/yyyy') : '') + '<td class="sg"></td></tr></table>' +
    '<div class="sk">F. UNTUK KEGUNAAN PIC KENDERAAN</div><table class="t">' + row('Kereta diserahkan pada', '') + row('Kereta dipulangkan pada', '') + '</table>' +
    '<table class="sgt"><tr>' + sign('Tandatangan PIC', picNama, 'PIC Kenderaan', '') + '<td class="sg"></td></tr></table>' +
    '<div class="ft">Dijana oleh IPTG iCar pada ' + Utilities.formatDate(new Date(), tz, 'dd/MM/yyyy, h:mm a') + (x.id ? ' · Rekod asal dalam tab PERMOHONAN PERIBADI' : '') + '</div>' +
    '</body></html>';
}
function adminPDFMohon(pin, id) {
  const ss = ssApp_(); semakPIN_(ss, pin);
  const x = id ? mohonBaris_(ss).find(r => r.id === String(id)) : null;
  if (id && !x) throw new Error('Permohonan tidak dijumpai.');
  const nama = x ? 'Borang Permohonan ' + x.id + ' ' + x.nama : 'Borang Permohonan Khas (kosong)';
  const blob = HtmlService.createHtmlOutput(htmlBorangMohon_(ss, x)).getAs('application/pdf').setName(nama + '.pdf');
  const folder = subfolder_(DriveApp.getFolderById(FOLDER_GAMBAR_IPTG), 'Borang Permohonan');
  const lama = folder.getFilesByName(nama + '.pdf');
  while (lama.hasNext()) lama.next().setTrashed(true);
  const fl = folder.createFile(blob);
  try { fl.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW); } catch (e) {}
  return { url: fl.getUrl(), unduh: 'https://drive.google.com/uc?export=download&id=' + fl.getId(), nama: fl.getName() };
}


